"""Food-picture-01 entry: pepperoni pizza cheese pull.

The entry image shows a hand lifting a slice of pepperoni pizza, with a
long stretch of melted mozzarella pulling away from the rest of the pie.
The crust is blistered from a hot oven and oven fire glows behind the
slice. It is built for the food-picture rubric: it makes the viewer
hungry, the food looks fresh and real, and the glossy cheese, crisped
pepperoni edges and blistered crust give texture you can almost feel.

How it works: the JPEG bytes of the photograph are embedded in this file
as a base64 blob. Running the program decodes the blob and writes the
exact same bytes to ``entry.png`` inside the output directory. The write
is fully deterministic: the same input bytes always produce the same
output file, byte for byte, with no timestamps, randomness or network
access involved. Only the Python standard library is used.
"""

