_OUTPUT_NAME = "entry.png"


def decode_image_bytes() -> bytes:
    """Decode the embedded base64 blob back to the original JPEG bytes."""
    if not _IMAGE_B64:
        raise RuntimeError("embedded image blob is empty")
    return base64.b64decode(_IMAGE_B64, validate=True)


def output_path() -> Path:
    """Resolve the output directory from the environment, default /output."""
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    return Path(out_dir) / _OUTPUT_NAME


def main() -> int:
    """Decode the embedded photo and write it deterministically.

    The write uses a single atomic-ish write_bytes call; the parent
    directory is created first so the program also works when the
    output directory does not exist yet. Nothing here depends on the
    clock, locale or network, so repeated runs are byte-identical.
    """
    image_bytes = decode_image_bytes()
    target = output_path()
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(image_bytes)
    print(f"wrote {target} ({len(image_bytes)} bytes)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
